const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '支点' },
      { kind: 'text', payload: '动力臂' },
      { kind: 'text', payload: '阻力臂' }
    ];
  },
  render: function (input, metrics) {
    var w = input.viewport.widthDu;
    var h = input.viewport.heightDu;
    var groundY = h * 0.82;
    var E = { x: w * 0.10, y: h * 0.46 };
    var R = { x: w * 0.80, y: h * 0.68 };
    var t = 5 / 7;
    var P = { x: E.x + (R.x - E.x) * t, y: E.y + (R.y - E.y) * t };
    var R2 = { x: R.x + w * 0.045, y: R.y + h * 0.012 };
    var yArm = h * 0.30;
    var fs = Math.max(12, Math.min(18, w * 0.025));
    var rockPts = [
      [R.x, groundY],
      [w * 0.79, h * 0.77],
      [w * 0.805, h * 0.69],
      [w * 0.835, h * 0.61],
      [w * 0.88, h * 0.575],
      [w * 0.93, h * 0.60],
      [w * 0.965, h * 0.68],
      [w * 0.955, groundY],
      [R.x, groundY]
    ];
    var fulcrumPts = [
      [P.x, P.y],
      [P.x - w * 0.055, groundY],
      [P.x + w * 0.055, groundY],
      [P.x, P.y]
    ];
    var ground = visualSdk.polyline([[w * 0.04, groundY], [w * 0.96, groundY]]);
    var bar = visualSdk.polyline([[E.x, E.y], [R2.x, R2.y]]);
    var fulcrum = visualSdk.polyline(fulcrumPts);
    var rock = visualSdk.polyline(rockPts);
    var pivotDot = visualSdk.circle(P.x, P.y, Math.max(4, w * 0.008));
    var extE = visualSdk.polyline([[E.x, yArm], [E.x, E.y]]);
    var extP = visualSdk.polyline([[P.x, yArm], [P.x, P.y]]);
    var extR = visualSdk.polyline([[R.x, yArm], [R.x, R.y]]);
    var midEP = (E.x + P.x) / 2;
    var midPR = (P.x + R.x) / 2;
    var arm1a = visualSdk.arrow(midEP, yArm, E.x, yArm, {});
    var arm1b = visualSdk.arrow(midEP, yArm, P.x, yArm, {});
    var arm2a = visualSdk.arrow(midPR, yArm, P.x, yArm, {});
    var arm2b = visualSdk.arrow(midPR, yArm, R.x, yArm, {});
    return {
      schemaVersion: 1,
      sceneId: 'crowbar-lever',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: w, height: h },
      paths: [
        { id: 'ground', commands: ground },
        { id: 'bar', commands: bar },
        { id: 'fulcrum', commands: fulcrum },
        { id: 'rock', commands: rock },
        { id: 'pivotDot', commands: pivotDot },
        { id: 'extE', commands: extE },
        { id: 'extP', commands: extP },
        { id: 'extR', commands: extR },
        { id: 'arm1a', commands: arm1a },
        { id: 'arm1b', commands: arm1b },
        { id: 'arm2a', commands: arm2a },
        { id: 'arm2b', commands: arm2b }
      ],
      root: {
        type: 'group',
        children: [
          { type: 'path', pathId: 'ground', fill: 'none', stroke: '#5b6470', strokeWidth: 2 },
          { type: 'path', pathId: 'bar', fill: 'none', stroke: '#3f3f3f', strokeWidth: 9 },
          { type: 'path', pathId: 'fulcrum', fill: '#e7c36a', stroke: '#7a5a1e', strokeWidth: 2 },
          { type: 'path', pathId: 'rock', fill: '#b7b0a3', stroke: '#6b6459', strokeWidth: 2 },
          { type: 'path', pathId: 'pivotDot', fill: '#d04a3a', stroke: '#7a1f16', strokeWidth: 1 },
          { type: 'path', pathId: 'extE', fill: 'none', stroke: '#7a8899', strokeWidth: 1 },
          { type: 'path', pathId: 'extP', fill: 'none', stroke: '#7a8899', strokeWidth: 1 },
          { type: 'path', pathId: 'extR', fill: 'none', stroke: '#7a8899', strokeWidth: 1 },
          { type: 'path', pathId: 'arm1a', fill: 'none', stroke: '#2c3e50', strokeWidth: 1.5 },
          { type: 'path', pathId: 'arm1b', fill: 'none', stroke: '#2c3e50', strokeWidth: 1.5 },
          { type: 'path', pathId: 'arm2a', fill: 'none', stroke: '#2c3e50', strokeWidth: 1.5 },
          { type: 'path', pathId: 'arm2b', fill: 'none', stroke: '#2c3e50', strokeWidth: 1.5 },
          { type: 'label', text: '动力臂', x: midEP, y: yArm - fs * 0.9, fontSize: fs, fill: '#1f2d3d', textAnchor: 'middle', dominantBaseline: 'middle' },
          { type: 'label', text: '阻力臂', x: midPR, y: yArm - fs * 0.9, fontSize: fs, fill: '#1f2d3d', textAnchor: 'middle', dominantBaseline: 'middle' },
          { type: 'label', text: '支点', x: P.x + w * 0.08, y: P.y - h * 0.015, fontSize: fs, fill: '#1f2d3d', textAnchor: 'middle', dominantBaseline: 'middle' }
        ]
      }
    };
  }
};
